const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const aoi = ee.Geometry.Point([141.780304, -27.667421]).buffer(10000);
  const date1_start = '2025-04-06';
  const date1_end = '2025-04-07';
  const date2_start = '2025-04-22';
  const date2_end = '2025-04-23';

  // Function to calculate NDVI
  const addNDVI = (image) => {
    const ndvi = image.normalizedDifference(['B8', 'B4']).rename('NDVI');
    return image.addBands(ndvi);
  };

  // Function to mask clouds using the QA60 band for Sentinel-2
  const maskS2clouds = (image) => {
    const qa = image.select('QA60');
    const cloudBitMask = 1 << 10;
    const cirrusBitMask = 1 << 11;
    const mask = qa.bitwiseAnd(cloudBitMask).eq(0)
                   .and(qa.bitwiseAnd(cirrusBitMask).eq(0));
    return image.updateMask(mask).divide(10000);
  };

  // 2. Data Acquisition & Check
  const s2Collection = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
                        .filterBounds(aoi);

  const collection1 = s2Collection.filterDate(date1_start, date1_end);
  const collection2 = s2Collection.filterDate(date2_start, date2_end);

  const size1 = collection1.size().getInfo();
  const size2 = collection2.size().getInfo();

  console.log(`Images found for April 6, 2025: ${size1}`);
  console.log(`Images found for April 22, 2025: ${size2}`);

  if (size1 === 0 || size2 === 0) {
    console.log("Reason: Dates are in the future, so no images are available.");
    console.log("C1");
    return;
  }

  // This part of the code will not be reached due to the dates being in the future.
  // It is included for completeness if the dates were historical.

  // 3. Processing
  const image1 = collection1.map(maskS2clouds).map(addNDVI).median();
  const image2 = collection2.map(maskS2clouds).map(addNDVI).median();

  // 4. Calculation
  const scale = 1000;
  const commonReducer = ee.Reducer.mean().combine({
    reducer2: ee.Reducer.count(),
    sharedInputs: true
  });

  const stats1 = image1.reduceRegion({
    reducer: commonReducer,
    geometry: aoi,
    scale: scale,
    maxPixels: 1e9
  });

  const stats2 = image2.reduceRegion({
    reducer: commonReducer,
    geometry: aoi,
    scale: scale,
    maxPixels: 1e9
  });

  const ndvi1 = stats1.get('NDVI_mean').getInfo();
  const count1 = stats1.get('NDVI_count').getInfo();

  const ndvi2 = stats2.get('NDVI_mean').getInfo();
  const count2 = stats2.get('NDVI_count').getInfo();

  console.log(`April 6, 2025: NDVI = ${ndvi1 ? ndvi1.toFixed(4) : 'N/A'}, Valid Pixels = ${count1}`);
  console.log(`April 22, 2025: NDVI = ${ndvi2 ? ndvi2.toFixed(4) : 'N/A'}, Valid Pixels = ${count2}`);

  if (count1 === 0 || count2 === 0) {
    console.log("No valid pixels after cloud masking in one or both periods.");
    console.log("C2");
    return;
  }

  if (ndvi1 === null || ndvi2 === null) {
      console.log("Calculation failed, result is null.");
      console.log("C3");
      return;
  }

  // 5. Validation & Final Answer
  if (ndvi2 > ndvi1) {
    console.log("A");
  } else {
    console.log("B");
  }

}

async function initEE() {
  try {
    await new Promise((resolve, reject) => {
      ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
    });
    await new Promise((resolve, reject) => {
      ee.initialize(null, null, resolve, reject);
    });
    await runAnalysis();
  } catch (e) {
    console.error(`Initialization or analysis failed: ${e}`);
    console.log("D");
  }
}

initEE();
